using System;
using System.IO;
using System.Reflection;
using AirBridge.Storage;
class DataLocationTests {
 static int checks;static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 static bool Reject(Action action){try{action();return false;}catch(IOException){return true;}}
 static int Main(){try{Run();return 0;}catch(Exception ex){Console.WriteLine("FAIL "+ex);return 1;}}
 static void Run(){string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"fixture-"+Guid.NewGuid().ToString("N")),app=Path.Combine(root,"app"),legacy=Path.Combine(root,"legacy");Directory.CreateDirectory(app);Directory.CreateDirectory(legacy);string launch=Path.Combine(app,"AirBridge.exe");File.WriteAllText(launch,"launcher fixture");
  string firstPortable=Path.Combine(app,"Data");
  Check(DataLocation.Resolve(launch,legacy,false,null).Root==firstPortable,"new installs default to Data beside the EXE");
  Check(!Directory.Exists(firstPortable),"read-only resolution does not create storage");
  Check(DataLocation.Resolve(launch,legacy,true,()=>true).Root==firstPortable&&Directory.Exists(firstPortable),"startup initializes writable portable storage");
  string journalOnly=Path.Combine(root,"journal-only");Directory.CreateDirectory(journalOnly);File.WriteAllText(Path.Combine(journalOnly,"AirBridge-app-routing-recovery.xml"),"<apps><app /></apps>");Check(DataLocation.Resolve(launch,journalOnly,false,null).Root==journalOnly,"unrestored legacy journal remains reachable without settings");
  string fallbackApp=Path.Combine(root,"blocked-app"),fallbackLegacy=Path.Combine(root,"fallback-legacy");Directory.CreateDirectory(fallbackApp);File.WriteAllText(Path.Combine(fallbackApp,"Data"),"keep");
  var fallback=DataLocation.Resolve(Path.Combine(fallbackApp,"AirBridge.exe"),fallbackLegacy,true,()=>true);Check(fallback.Root==fallbackLegacy&&fallback.Notice!=""&&File.ReadAllText(Path.Combine(fallbackApp,"Data"))=="keep","unwritable portable storage falls back with notice without overwriting files");
  File.WriteAllText(Path.Combine(legacy,"settings.json"),"{\"AutoConnect\":true}");File.WriteAllText(Path.Combine(legacy,"phone-battery.json"),"battery");File.WriteAllText(Path.Combine(legacy,"sample.log"),"log");File.WriteAllText(Path.Combine(legacy,"recording.wav"),"recording");string journal=Path.Combine(legacy,"AirBridge-default-output-recovery.xml");File.WriteAllText(journal,"<defaults />");Directory.CreateDirectory(Path.Combine(legacy,"runtime"));File.WriteAllText(Path.Combine(legacy,"runtime","loaded.dll"),"cache");Directory.CreateDirectory(Path.Combine(legacy,"updates"));File.WriteAllText(Path.Combine(legacy,"updates","backup.exe"),"old executable");
  Check(DataLocation.Resolve(launch,legacy,false,null).Root==legacy,"existing unconfigured profiles retain settings and recovery journals");
  File.WriteAllText(Path.Combine(firstPortable,"settings.json"),"portable profile");Check(DataLocation.Resolve(launch,legacy,false,null).Root==firstPortable,"existing portable profile takes precedence over legacy profile");File.Delete(Path.Combine(firstPortable,"settings.json"));
  DataLocation.Request(launch,legacy,legacy,"portable","",true);string portable=Path.Combine(app,"Data");Check(File.Exists(DataLocation.Pointer(launch)),"location file saved beside launcher");Check(DataLocation.HasPending(launch),"migration staged rather than applied immediately");Check(DataLocation.Resolve(launch,legacy,false,null).Root==legacy&&!File.Exists(Path.Combine(portable,"settings.json")),"running helpers retain old root");
  var waiting=DataLocation.Resolve(launch,legacy,true,()=>false);Check(waiting.Root==legacy&&DataLocation.HasPending(launch),"busy recovery prevents migration");File.WriteAllText(journal,"<defaults><role id=\"1\" /></defaults>");waiting=DataLocation.Resolve(launch,legacy,true,()=>true);Check(waiting.Root==legacy&&DataLocation.HasPending(launch),"pending output journal prevents migration");File.WriteAllText(journal,"<defaults />");
  var moved=DataLocation.Resolve(launch,legacy,true,()=>true);Check(moved.Root==portable&&!DataLocation.HasPending(launch),"quiescent migration activates portable root");Check(File.ReadAllText(Path.Combine(portable,"settings.json"))==File.ReadAllText(Path.Combine(legacy,"settings.json")),"configuration copied intact");Check(File.ReadAllText(Path.Combine(portable,"sample.log"))=="log","logs copied");Check(File.Exists(Path.Combine(legacy,"settings.json")),"original data retained");Check(!Directory.Exists(Path.Combine(portable,"runtime"))&&!Directory.Exists(Path.Combine(portable,"updates")),"loaded caches and update backups not copied");
  Check(!File.Exists(Path.Combine(portable,"recording.wav"))&&File.Exists(Path.Combine(legacy,"recording.wav")),"recordings remain at their chosen location");var descriptor=new System.Xml.XmlDocument();descriptor.Load(DataLocation.Pointer(launch));Check(descriptor.DocumentElement.GetAttribute("path")=="","portable descriptor does not pin a personal absolute path");
  string movedApp=Path.Combine(root,"moved-app");Directory.Move(app,movedApp);launch=Path.Combine(movedApp,"AirBridge.exe");portable=Path.Combine(movedApp,"Data");Check(DataLocation.Resolve(launch,legacy,false,null).Root==portable,"portable root follows executable directory move");
  string custom=Path.Combine(root,"custom");DataLocation.Request(launch,portable,legacy,"custom",custom,true);Check(DataLocation.Resolve(launch,legacy,true,()=>true).Root==custom,"custom root activated on next start");Check(File.Exists(Path.Combine(custom,"settings.json")),"custom migration preserves settings");
  string existing=Path.Combine(root,"existing");Directory.CreateDirectory(existing);File.WriteAllText(Path.Combine(existing,"settings.json"),"existing profile");Check(Reject(()=>DataLocation.Request(launch,custom,legacy,"custom",existing,true)),"nonempty destination cannot be overwritten by migration");DataLocation.Request(launch,custom,legacy,"custom",existing,false);Check(DataLocation.Resolve(launch,legacy,true,()=>true).Root==existing&&File.ReadAllText(Path.Combine(existing,"settings.json"))=="existing profile","explicit use-existing does not merge profiles");
  DataLocation.Request(launch,existing,legacy,"default","",false);DataLocation.Cancel(launch);Check(!DataLocation.HasPending(launch)&&DataLocation.Resolve(launch,legacy,false,null).Root==existing,"cancel retains active location");
  DataLocation.Request(launch,existing,legacy,"default","",false);Check(DataLocation.Resolve(launch,legacy,true,()=>true).Root==legacy,"explicit Windows data directory choice is preserved");DataLocation.Request(launch,legacy,legacy,"custom",existing,false);Check(DataLocation.Resolve(launch,legacy,true,()=>true).Root==existing,"explicit custom location overrides portable default");
  Check(Reject(()=>DataLocation.Request(launch,existing,legacy,"custom",Path.Combine(existing,"nested"),true)),"nested data folders rejected");Check(Reject(()=>DataLocation.Request(launch,existing,legacy,"custom",Path.GetPathRoot(root),false)),"drive root rejected");
  string fresh=Path.Combine(root,"fresh");DataLocation.Request(launch,existing,legacy,"custom",fresh,true);File.WriteAllText(Path.Combine(fresh,"new-user-file.txt"),"keep");var failed=DataLocation.Resolve(launch,legacy,true,()=>true);Check(failed.Root==existing&&DataLocation.HasPending(launch)&&File.ReadAllText(Path.Combine(fresh,"new-user-file.txt"))=="keep","destination changed after scheduling remains untouched");DataLocation.Cancel(launch);
  string pointer=DataLocation.Pointer(launch);Check(File.Exists(pointer+".bak"),"location file has atomic backup");
  Console.WriteLine("PASS data location total="+checks+"; fixture folders only; no AppData, UI or system output changes");
 }
}
